int kvm_ioctl_create_device(struct kvm *kvm, struct kvm_create_device *cd)
{
	struct kvm_device_ops *ops;
	struct kvm_device *dev;
	int r, create_type;

	if (cd->type >= KVM_DEV_TYPE_MAX)
		return -EINVAL;

	ops = kvm_device_ops[cd->type];
	if (!ops)
		return -EINVAL;

	if (cd->flags & KVM_CREATE_DEVICE_TEST)
		return 0;

	dev = kzalloc(sizeof(*dev), GFP_KERNEL);
	if (!dev)
		return -ENOMEM;

	dev->kvm = kvm;
	dev->ops = ops;

	mutex_lock(&kvm->lock);
	r = -EEXIST;
	list_for_each_entry(dev, &kvm->devices, list)
		if (dev->ops == ops) {
			if (cd->fd != 0) {
				r = -EINVAL;
				goto unlock;
			}
			cd->fd = get_fd();
			dev->fd = cd->fd;
			break;
		}
	if (r == -EEXIST)
		goto unlock;

	r = ops->create(dev, cd);
	if (r)
		goto unlock;

	list_add(&dev->list, &kvm->devices);
	if (ops->init)
		ops->init(dev);

	cd->fd = get_fd();
	dev->fd = cd->fd;

unlock:
	mutex_unlock(&kvm->lock);

	if (r)
		kfree(dev);

	return r;
}

int kvm_create_device(struct kvm *kvm, struct kvm_create_device *cd)
{
	struct kvm_device_ops *ops;
	struct kvm_device *dev;
	int r = 0;

	if (cd->type >= KVM_DEV_TYPE_MAX)
		return -EINVAL;

	ops = kvm_dev_ops[cd->type];
	if (!ops)
		return -ENODEV;

	if (cd->flags & KVM_CREATE_DEVICE_TEST)
		return 0;

	dev = kzalloc(ops->size, GFP_KERNEL);
	if (!dev)
		return -ENOMEM;

	kvm_lock(kvm);
	r = ops->create(dev, kvm);
	if (r) {
		kvm_unlock(kvm);
		goto out_free;
	}

	list_add(&dev->list, &kvm->devices);
	dev->ops = ops;
	dev->kvm = kvm;
	if (ops->init) {
		r = ops->init(dev);
		if (r)
			goto out_remove;
	}

	dev->fd = get_unused_fd_flags(0);
	if (dev->fd < 0) {
		r = dev->fd;
		goto out_deinit;
	}

	fd_install(dev->fd, dev->poll);
	kvm_unlock(kvm);

	return 0;

out_deinit:
	if (ops->init)
		ops->init(dev);
out_remove:
	list_del(&dev->list);
out_free:
	kfree(dev);
	return r;
}

