int kvm_device_create(struct kvm *kvm, struct kvm_create_device *cd)
{
	struct kvm_device *dev;
	const struct kvm_device_ops *ops;
	int r = 0;

	ops = kvm_find_device_ops(cd->type);
	if (!ops)
		return -ENOENT;

	if (cd->flags & KVM_CREATE_DEVICE_TEST)
		return 0;

	dev = kzalloc(sizeof(*dev), GFP_KERNEL);
	if (!dev)
		return -ENOMEM;

	mutex_lock(&kvm->lock);
	r = ops->create(dev, cd->fd, kvm);
	if (r) {
		mutex_unlock(&kvm->lock);
		goto out_free;
	}

	list_add(&dev->list, &kvm->devices);
	dev->ops = ops;
	mutex_unlock(&kvm->lock);

	if (ops->init)
		ops->init(dev);

	r = kvm_dev_ioctl_create_device(dev, cd->fd);
	if (r)
		goto out_destroy;

	return 0;

out_destroy:
	mutex_lock(&kvm->lock);
	list_del(&dev->list);
	mutex_unlock(&kvm->lock);
	ops->destroy(dev);
out_free:
	kfree(dev);
	return r;
}

int kvm_dev_create(struct kvm *kvm, struct kvm_create_device *cd)
{
	struct kvm_device_ops *ops;
	struct kvm_device *dev;
	int r = -EINVAL;

	if (!cd->type)
		goto out;

	ops = kvm_find_device_ops(cd->type);
	if (!ops)
		goto out;

	if (cd->flags & KVM_CREATE_DEVICE_TEST)
		return 0;

	dev = ops->create(cd->fd);
	if (IS_ERR(dev)) {
		r = PTR_ERR(dev);
		goto out;
	}

	mutex_lock(&kvm->lock);
	list_add(&dev->list, &kvm->devices);
	mutex_unlock(&kvm->lock);

	dev->kvm = kvm;
	dev->id = cd->type;

	if (ops->init) {
		r = ops->init(dev);
		if (r)
			goto fail;
	}

	cd->fd = get_unused_fd_flags(0);
	if (cd->fd < 0)
		goto fail;

	fd_install(cd->fd, dev->fd);
	return 0;

fail:
	list_del(&dev->list);
	mutex_unlock(&kvm->lock);
	if (ops->release)
		ops->release(dev);
	return r;
}

#include <linux/kvm.h>
