int kvm_device_create(struct kvm *kvm, struct kvm_create_device *cd)
{
	struct kvm_dev_ops *ops;
	struct kvm_device *dev;
	int r = 0;

	ops = kvm_find_device_ops(cd->type);
	if (!ops)
		return -EINVAL;

	if (cd->flags & KVM_CREATE_DEVICE_TEST)
		return 0;

	dev = kzalloc(sizeof(*dev), GFP_KERNEL_ACCOUNT);
	if (!dev)
		return -ENOMEM;

	kvm_lock(kvm);
	r = ops->create(dev, kvm);
	if (r) {
		kvm_unlock(kvm);
		goto fail_free_dev;
	}

	list_add(&dev->list, &kvm->devices);
	dev->ops = ops;
	if (ops->init && ops->init(dev))
		goto fail_destroy;

	r = kvm_create_device_fd(kvm, dev, cd->flags, &dev->fd);
	if (r)
		goto fail_destroy;

	kvm_unlock(kvm);
	return 0;

fail_destroy:
	ops->destroy(dev);
	kvm_unlock(kvm);
fail_free_dev:
	kfree(dev);
	return r;
}
